29	public class CatalogAccessControlRule
30	{
31	    private final AccessMode accessMode;
32	    private final Optional<Pattern> userRegex;
33	    private final Optional<Pattern> catalogRegex;
34	
35	    @JsonCreator
36	    public CatalogAccessControlRule(
37	            @JsonProperty("allow") AccessMode accessMode,
38	            @JsonProperty("user") Optional<Pattern> userRegex,
39	            @JsonProperty("catalog") Optional<Pattern> catalogRegex)
40	    {
41	        this.accessMode = requireNonNull(accessMode, "accessMode is null");
42	        this.userRegex = requireNonNull(userRegex, "userRegex is null");
43	        this.catalogRegex = requireNonNull(catalogRegex, "catalogRegex is null");
44	    }
45	
46	    public Optional<AccessMode> match(String user, String catalog)
47	    {
48	        if (userRegex.map(regex -> regex.matcher(user).matches()).orElse(true) &&
49	                catalogRegex.map(regex -> regex.matcher(catalog).matches()).orElse(true)) {
50	            return Optional.of(accessMode);
51	        }
52	        return Optional.empty();
53	    }
54	
55	    public enum AccessMode
56	    {
57	        ALL("all"),
58	        READ_ONLY("read-only"),
59	        NONE("none");
60	
61	        private static final Map<String, AccessMode> modeByName = Maps.uniqueIndex(ImmutableList.copyOf(AccessMode.values()), AccessMode::toString);
62	
63	        private final String stringValue;
64	
65	        AccessMode(String stringValue)
66	        {
