70	        @JsonValue
71	        @Override
72	        public String toString()
73	        {
74	            return stringValue;
75	        }
76	
77	        @JsonCreator
78	        public static AccessMode fromJson(Object value)
79	        {
80	            if (Boolean.TRUE.equals(value)) {
81	                return ALL;
82	            }
83	            if (Boolean.FALSE.equals(value)) {
84	                return NONE;
85	            }
86	            if (value instanceof String) {
87	                AccessMode accessMode = modeByName.get(((String) value).toLowerCase(Locale.US));
88	                if (accessMode != null) {
89	                    return accessMode;
90	                }
91	            }
92	
93	            throw new IllegalArgumentException("Unknown " + AccessMode.class.getSimpleName() + ": " + value);
94	        }
95	
96	        boolean implies(AccessMode other)
97	        {
98	            if (this == ALL && other == READ_ONLY) {
99	                return true;
100	            }
101	            return this == other;
102	        }
103	    }
